/**
 * GamiFrench professional sound engine.
 *
 * One central place for every interactive sound in the app:
 * quiz answers, sentence-builder tiles, speaking checks, stars,
 * level-ups, chests, streaks, navigation taps.
 *
 * Design notes:
 *  - Built on `expo-audio` (already a dependency) via `createAudioPlayer`,
 *    so sounds work offline, on Android / iOS / Web, with no network.
 *  - All clips are local WAV files in `assets/sounds/` generated by
 *    `tools/generate_sounds.py` — royalty-free, synthesized, no licensing.
 *  - Players are created lazily and reused; `seekTo(0)` before `play()`
 *    keeps rapid taps snappy and allows overlap-safe replay.
 *  - A global enabled flag is persisted in SecureStore and mirrored from
 *    the backend `sound_enabled` setting, so Settings can mute all SFX.
 *  - Every method is fire-and-forget and never throws: a missing audio
 *    device must never break a lesson.
 */

import { createAudioPlayer, setAudioModeAsync } from 'expo-audio';
import * as SecureStore from 'expo-secure-store';

const SOUND_ENABLED_KEY = 'gamifrench.sound-enabled';
const MUSIC_ENABLED_KEY = 'gamifrench.music-enabled';

let enabled = true;
let musicEnabled = true;
/*
 * Audio stays fully silent until a login succeeds. The root layout only
 * preloads players; `unlockAudio()` (called by AuthProvider on sign-in /
 * session restore) opens the gate, and `lockAudio()` on sign-out closes it.
 */
let audioUnlocked = false;
let modeConfigured = false;
let musicStarting = false;
const players = {};
let musicPlayer = null;

const SOURCES = {
  // Quiz / practice feedback
  correct: require('../../assets/sounds/correct.wav'),
  wrong: require('../../assets/sounds/wrong.wav'),
  // Sentence builder + generic UI
  pop: require('../../assets/sounds/pop.wav'),
  tap: require('../../assets/sounds/tap.wav'),
  whoosh: require('../../assets/sounds/whoosh.wav'),
  // Rewards & milestones
  star: require('../../assets/sounds/star.wav'),
  levelup: require('../../assets/sounds/levelup.wav'),
  reward: require('../../assets/sounds/reward.wav'),
  streak: require('../../assets/sounds/streak.wav'),
  complete: require('../../assets/sounds/complete.wav'),
  // Speaking lab
  listen: require('../../assets/sounds/listen.wav'),
  great: require('../../assets/sounds/great.wav'),
};

const MUSIC_SOURCE = require('../../assets/sounds/background.wav');
/** Gentle bed under gameplay — never competes with TTS or SFX. */
const MUSIC_VOLUME = 0.22;

async function ensureMode() {
  if (modeConfigured) return;
  modeConfigured = true;
  try {
    // SFX should mix with lesson TTS / music, never grab exclusive focus.
    await setAudioModeAsync({
      playsInSilentMode: true,
      interruptionMode: 'mixWithOthers',
    });
  } catch {
    // Audio mode is best-effort; playback still works with defaults.
  }
}

function playerFor(name) {
  if (!players[name]) {
    try {
      const player = createAudioPlayer(SOURCES[name]);
      player.volume = 1.0;
      players[name] = player;
    } catch {
      return null;
    }
  }
  return players[name] ?? null;
}

async function playSound(name) {
  // Silent until a login succeeds — no taps/chimes on login/register.
  if (!audioUnlocked || !enabled) return;
  if (!SOURCES[name]) return;
  try {
    await ensureMode();
    const player = playerFor(name);
    if (!player) return;
    try {
      // Restart instantly on rapid taps; skip seek when already at 0.
      if (player.currentTime > 0.02) await player.seekTo(0);
    } catch {
      // Very short clips may report no seekable range; play anyway.
    }
    player.play();
  } catch {
    // Sound must never break gameplay.
  }
}

/* ------------------------------------------------------------------ */
/* Background music (separate looping player + toggle)                 */
/* ------------------------------------------------------------------ */

function ensureMusicPlayer() {
  if (!musicPlayer) {
    try {
      musicPlayer = createAudioPlayer(MUSIC_SOURCE);
      musicPlayer.volume = MUSIC_VOLUME;
      musicPlayer.loop = true;
    } catch {
      musicPlayer = null;
    }
  }
  return musicPlayer;
}

/** Start the gentle looping ambience (only after login + when music is on). */
export async function startMusic() {
  if (!audioUnlocked || !musicEnabled || musicStarting) return;
  musicStarting = true;
  try {
    await ensureMode();
    const player = ensureMusicPlayer();
    if (!player) return;
    if (!player.playing) player.play();
  } catch {
    // Ambience is decorative; never fatal.
  } finally {
    musicStarting = false;
  }
}

/** Pause the ambience (keeps position; startMusic resumes). */
export function pauseMusic() {
  try {
    if (musicPlayer?.playing) musicPlayer.pause();
  } catch {
    // ignore
  }
}

/** Turn background music on/off (persisted on this device). */
export async function setMusicEnabled(value) {
  musicEnabled = value !== false;
  try {
    await SecureStore.setItemAsync(MUSIC_ENABLED_KEY, musicEnabled ? '1' : '0');
  } catch {
    // Persistence is best-effort; in-memory flag still applies.
  }
  if (musicEnabled) startMusic();
  else pauseMusic();
}

export function isMusicEnabled() {
  return musicEnabled;
}

export async function loadMusicEnabled() {
  try {
    const stored = await SecureStore.getItemAsync(MUSIC_ENABLED_KEY);
    if (stored === '0') musicEnabled = false;
    else if (stored === '1') musicEnabled = true;
  } catch {
    // Keep default (on).
  }
  return musicEnabled;
}

/** Mirror the backend `music_enabled` preference locally. */
export async function syncMusicEnabledFromServer(value) {
  if (typeof value === 'boolean') await setMusicEnabled(value);
}

/**
 * Open the audio gate after a successful login (or a restored session).
 * Restores persisted toggles, then starts the ambience when allowed.
 */
export async function unlockAudio() {
  audioUnlocked = true;
  await loadSoundEnabled();
  const musicOn = await loadMusicEnabled();
  preloadSounds();
  if (musicOn) startMusic();
  return { sound: enabled, music: musicOn };
}

/** Close the audio gate on sign-out: stop ambience, silence all SFX. */
export function lockAudio() {
  audioUnlocked = false;
  pauseMusic();
}

/** Whether login has opened the audio gate yet. */
export function isAudioUnlocked() {
  return audioUnlocked;
}

/** Turn all game sounds on/off (persisted on this device). */
export async function setSoundEnabled(value) {
  enabled = value !== false;
  try {
    await SecureStore.setItemAsync(SOUND_ENABLED_KEY, enabled ? '1' : '0');
  } catch {
    // Persistence is best-effort; in-memory flag still applies.
  }
}

/** Current mute state (in-memory; call loadSoundEnabled() at startup). */
export function isSoundEnabled() {
  return enabled;
}

/** Restore the persisted mute state. Call once from the root layout. */
export async function loadSoundEnabled() {
  try {
    const stored = await SecureStore.getItemAsync(SOUND_ENABLED_KEY);
    if (stored === '0') enabled = false;
    else if (stored === '1') enabled = true;
  } catch {
    // Keep default (on).
  }
  return enabled;
}

/**
 * Mirror the backend `sound_enabled` preference locally.
 * The settings screen shows the server value; calling this keeps the
 * engine in sync without an extra round-trip elsewhere.
 */
export async function syncSoundEnabledFromServer(value) {
  if (typeof value === 'boolean') await setSoundEnabled(value);
}

/**
 * Whether this device has its own saved choice for sound / music. Settings
 * keeps a device choice over the server copy (sound is a per-device thing),
 * and adopts the server value only on a device that never chose.
 */
export async function hasStoredAudioChoice(kind = 'sound') {
  try {
    const stored = await SecureStore.getItemAsync(
      kind === 'music' ? MUSIC_ENABLED_KEY : SOUND_ENABLED_KEY
    );
    return stored === '0' || stored === '1';
  } catch {
    return false;
  }
}

/** Pre-create players so the first tap has zero delay. */
export function preloadSounds(names = Object.keys(SOURCES)) {
  try {
    ensureMode();
    names.forEach((name) => {
      if (SOURCES[name]) playerFor(name);
    });
    ensureMusicPlayer();
  } catch {
    // Preloading is best-effort.
  }
}

export const sounds = {
  /** Quiz / practice answered correctly. */
  correct: () => playSound('correct'),
  /** Quiz / practice answered incorrectly (soft, encouraging). */
  wrong: () => playSound('wrong'),
  /** Sentence-builder word tile tapped. */
  pop: () => playSound('pop'),
  /** Generic button / card tap. */
  tap: () => playSound('tap'),
  /** Screen advance / continue whoosh. */
  whoosh: () => playSound('whoosh'),
  /** Star earned / rating reveal. */
  star: () => playSound('star'),
  /** Level up fanfare. */
  levelup: () => playSound('levelup'),
  /** Chest / mission reward claimed. */
  reward: () => playSound('reward'),
  /** Streak milestone crackle. */
  streak: () => playSound('streak'),
  /** Lesson / topic complete jingle. */
  complete: () => playSound('complete'),
  /** Speaking check started listening. */
  listen: () => playSound('listen'),
  /** Speaking scored well. */
  great: () => playSound('great'),
  /** Ambience controls (also exported standalone). */
  startMusic,
  pauseMusic,
};

export default sounds;
